<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$tienda=(int)($_POST['tienda_id']??0);$nombre=trim((string)($_POST['nombre']??''));$orden=max(0,(int)($_POST['orden']??0));if(!$tienda||$nombre===''){http_response_code(400);exit('Completa los datos.');}$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('INSERT INTO categorias (tienda_id,nombre,orden) VALUES (?,?,?)');$q->execute([$tienda,$nombre,$orden]);header('Location: categorias-admin.php?created=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo crear la categoría.');}
